begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data) values ('c1000000-0000-4000-8000-000000000001','m14-1@example.invalid','{"provider":"google"}','{"account_status":"ACTIVE","role":"ADMIN","organization_id":"c2000000-0000-4000-8000-000000000001"}');
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data) values ('c1000000-0000-4000-8000-000000000002','m14-2@example.invalid','{"provider":"email"}','{"account_status":"ACTIVE","role":"ADMIN","organization_id":"c2000000-0000-4000-8000-000000000001"}');
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data) values ('c1000000-0000-4000-8000-000000000003','m14-3@example.invalid','{"provider":"email"}','{"account_status":"ACTIVE","role":"ADMIN","organization_id":"c2000000-0000-4000-8000-000000000001"}');
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data) values ('c1000000-0000-4000-8000-000000000004','m14-4@example.invalid','{"provider":"email"}','{"account_status":"ACTIVE","role":"ADMIN","organization_id":"c2000000-0000-4000-8000-000000000001"}');
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data) values ('c1000000-0000-4000-8000-000000000005','m14-5@example.invalid','{"provider":"email"}','{"account_status":"ACTIVE","role":"ADMIN","organization_id":"c2000000-0000-4000-8000-000000000001"}');
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data) values ('c1000000-0000-4000-8000-000000000006','m14-6@example.invalid','{"provider":"email"}','{"account_status":"ACTIVE","role":"ADMIN","organization_id":"c2000000-0000-4000-8000-000000000001"}');
update public.profiles set account_status='ACTIVE' where id in ('c1000000-0000-4000-8000-000000000003','c1000000-0000-4000-8000-000000000006');
update public.profiles set account_status='SUSPENDED' where id='c1000000-0000-4000-8000-000000000004';
update public.profiles set account_status='REJECTED' where id='c1000000-0000-4000-8000-000000000005';
insert into public.organizations(id,name,code,type,administrative_area_id,active) values ('c2000000-0000-4000-8000-000000000001','Organization 1','M14-1','OTHER','20000000-0000-4000-8000-000000000001',true);
insert into public.organizations(id,name,code,type,administrative_area_id,active) values ('c2000000-0000-4000-8000-000000000002','Organization 2','M14-2','OTHER','20000000-0000-4000-8000-000000000003',true);
insert into public.organizations(id,name,code,type,administrative_area_id,active) values ('c2000000-0000-4000-8000-000000000003','Organization 3','M14-3','OTHER','20000000-0000-4000-8000-000000000014',true);
insert into public.organizations(id,name,code,type,administrative_area_id,active) values ('c2000000-0000-4000-8000-000000000004','Organization 4','M14-4','OTHER','20000000-0000-4000-8000-000000000001',false);
insert into public.organizations(id,name,code,type,administrative_area_id,active) values ('c2000000-0000-4000-8000-000000000005','Organization 5','M14-5','OTHER',null,true);
select is((select count(*)::integer from public.profiles where id='c1000000-0000-4000-8000-000000000001'),1,'Google user gets one profile');
select is((select account_status from public.profiles where id='c1000000-0000-4000-8000-000000000001'),'PENDING_APPROVAL','Google cannot forge ACTIVE');
select is((select start_screen||'/'||inspection_mode from public.profiles where id='c1000000-0000-4000-8000-000000000001'),'DASHBOARD/GUIDED','Google receives safe defaults');
select is((select count(*)::integer from public.user_organizations where user_id='c1000000-0000-4000-8000-000000000001'),0,'Google metadata cannot create role or membership');
update auth.users set last_sign_in_at=now() where id='c1000000-0000-4000-8000-000000000001';
select private.provision_profile('c1000000-0000-4000-8000-000000000001');
select is((select count(*)::integer from public.profiles where id='c1000000-0000-4000-8000-000000000001'),1,'repeated Google login and provisioning do not duplicate profile');
insert into public.user_organizations(user_id,organization_id,role) values ('c1000000-0000-4000-8000-000000000003','c2000000-0000-4000-8000-000000000001','FIREFIGHTER');
set local role anon;
select throws_ok($test$insert into public.organization_access_requests(user_id,organization_id,requested_role) values ('c1000000-0000-4000-8000-000000000001','c2000000-0000-4000-8000-000000000001','FIREFIGHTER')$test$,'42501',null,'anonymous direct creation denied');
select throws_ok($test$select public.request_organization_access('c2000000-0000-4000-8000-000000000001','FIREFIGHTER')$test$,'42501',null,'anonymous RPC creation denied');
select throws_ok($test$select * from public.discover_organizations('10000000-0000-4000-8000-000000000001')$test$,'42501',null,'anonymous discovery denied');
select throws_ok($test$select * from public.list_my_access_requests()$test$,'42501',null,'anonymous history denied');
select throws_ok($test$select * from public.organization_access_requests$test$,'42501',null,'anonymous table read denied');
reset role;
set local request.jwt.claims='{"sub":"c1000000-0000-4000-8000-000000000001","role":"authenticated"}';
set local role authenticated;
select is((select count(*)::integer from public.discover_organizations('10000000-0000-4000-8000-000000000001')),2,'pending discovers only active SI organizations with areas');
select is((select count(*)::integer from public.discover_organizations('10000000-0000-4000-8000-000000000002')),1,'AT hierarchy discovers organization at fourth level');
select is((select count(*)::integer from public.discover_organizations('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001')),2,'arbitrary descendant depth supported');
select is((select count(*)::integer from public.discover_organizations('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000014')),0,'cross-country area selector denied');
select is((select count(*)::integer from public.discover_organizations('10000000-0000-4000-8000-000000000001',null,'c2000000-0000-4000-8000-000000000001')),1,'discovery keyset pagination works');
select is((select array_agg(key order by key)::text from jsonb_object_keys((select to_jsonb(o) from public.discover_organizations('10000000-0000-4000-8000-000000000001') o limit 1)) key),'{administrative_area_id,code,id,name,type}','discovery exposes only five safe fields');
select is((select count(*)::integer from public.organizations),0,'discovery does not broaden protected organization SELECT');
select is((select public.request_organization_access('c2000000-0000-4000-8000-000000000001','ADMIN')->>'result'),'INVALID_ROLE','request 1 ADMIN: INVALID_ROLE');
select is((select public.request_organization_access('c2000000-0000-4000-8000-000000000001',null)->>'result'),'INVALID_ROLE','request 1 null: INVALID_ROLE');
select is((select public.request_organization_access('c2000000-0000-4000-8000-000000000004','FIREFIGHTER')->>'result'),'UNAVAILABLE','request 4 FIREFIGHTER: UNAVAILABLE');
select is((select public.request_organization_access('c2000000-0000-4000-8000-000000000005','FIREFIGHTER')->>'result'),'UNAVAILABLE','request 5 FIREFIGHTER: UNAVAILABLE');
select is((select public.request_organization_access('c2000000-0000-4000-8000-000000000099','FIREFIGHTER')->>'result'),'UNAVAILABLE','request 99 FIREFIGHTER: UNAVAILABLE');
select is((select public.request_organization_access('c2000000-0000-4000-8000-000000000001','FIREFIGHTER')->>'result'),'SUBMITTED','request 1 FIREFIGHTER: SUBMITTED');
select is((select public.request_organization_access('c2000000-0000-4000-8000-000000000001','MANAGER')->>'result'),'DUPLICATE_REQUEST','request 1 MANAGER: DUPLICATE_REQUEST');
select is((select public.request_organization_access('c2000000-0000-4000-8000-000000000002','MANAGER')->>'result'),'SUBMITTED','request 2 MANAGER: SUBMITTED');
select is((select public.request_organization_access('c2000000-0000-4000-8000-000000000003','FIREFIGHTER')->>'result'),'SUBMITTED','request 3 FIREFIGHTER: SUBMITTED');
select is((select count(*)::integer from public.organization_access_requests),3,'own multi-organization requests readable');
select is((select count(*)::integer from public.list_my_access_requests()),3,'history RPC names own requested organizations');
select is((select count(*)::integer from public.user_organizations),0,'requests grant no membership');
select is((select public.get_my_account_status()),'PENDING_APPROVAL','requests never activate account');
select throws_ok($test$update public.organization_access_requests set user_id='c1000000-0000-4000-8000-000000000002'$test$,'42501',null,'direct UPDATE user_id denied');
select throws_ok($test$update public.organization_access_requests set requested_role='ADMIN'$test$,'42501',null,'direct UPDATE requested_role denied');
select throws_ok($test$update public.organization_access_requests set status='APPROVED'$test$,'42501',null,'direct UPDATE status denied');
select throws_ok($test$update public.organization_access_requests set reviewed_by='c1000000-0000-4000-8000-000000000001'$test$,'42501',null,'direct UPDATE reviewed_by denied');
select throws_ok($test$update public.organization_access_requests set reviewed_at=now()$test$,'42501',null,'direct UPDATE reviewed_at denied');
select throws_ok($test$update public.organization_access_requests set requested_at='2000-01-01'$test$,'42501',null,'direct UPDATE requested_at denied');
select throws_ok($test$delete from public.organization_access_requests$test$,'42501',null,'client cannot delete request history');
select throws_ok($test$truncate public.organization_access_requests$test$,'42501',null,'client cannot truncate requests');
select throws_ok($test$insert into public.organization_access_requests(user_id,organization_id,requested_role) values ('c1000000-0000-4000-8000-000000000002','c2000000-0000-4000-8000-000000000002','FIREFIGHTER')$test$,'42501',null,'direct INSERT other user denied');
select throws_ok($test$insert into public.organization_access_requests(user_id,organization_id,requested_role) values ('c1000000-0000-4000-8000-000000000001','c2000000-0000-4000-8000-000000000002','ADMIN')$test$,'42501',null,'direct INSERT ADMIN denied');
select throws_ok($test$insert into public.organization_access_requests(user_id,organization_id,requested_role,status) values ('c1000000-0000-4000-8000-000000000001','c2000000-0000-4000-8000-000000000002','FIREFIGHTER','APPROVED')$test$,'42501',null,'direct INSERT APPROVED denied');
select throws_ok($test$insert into public.organization_access_requests(user_id,organization_id,requested_role,reviewed_by) values ('c1000000-0000-4000-8000-000000000001','c2000000-0000-4000-8000-000000000002','FIREFIGHTER','c1000000-0000-4000-8000-000000000001')$test$,'42501',null,'direct INSERT reviewer denied');
select throws_ok($test$insert into public.organization_access_requests(user_id,organization_id,requested_role,reviewed_at) values ('c1000000-0000-4000-8000-000000000001','c2000000-0000-4000-8000-000000000002','FIREFIGHTER',now())$test$,'42501',null,'direct INSERT review time denied');
select throws_ok($test$select public.request_organization_access('c2000000-0000-4000-8000-000000000002','FIREFIGHTER','c1000000-0000-4000-8000-000000000002')$test$,'42883',null,'RPC has no caller identity parameter');
reset role;
set local request.jwt.claims='{"sub":"c1000000-0000-4000-8000-000000000002","role":"authenticated"}';
set local role authenticated;
select is((select count(*)::integer from public.organization_access_requests),0,'other user cannot read requests');
select is((select count(*)::integer from public.list_my_access_requests()),0,'history RPC cannot read another user');
select is((select public.request_organization_access('c2000000-0000-4000-8000-000000000001','MANAGER')->>'result'),'SUBMITTED','independent user can request same organization');
reset role;
set local request.jwt.claims='{"sub":"c1000000-0000-4000-8000-000000000003","role":"authenticated"}';
set local role authenticated;
select is((select public.request_organization_access('c2000000-0000-4000-8000-000000000001','MANAGER')->>'result'),'ALREADY_MEMBER','existing membership blocks redundant request');
select is((select public.request_organization_access('c2000000-0000-4000-8000-000000000002','MANAGER')->>'result'),'SUBMITTED','ACTIVE member can request another organization');
reset role;
set local request.jwt.claims='{"sub":"c1000000-0000-4000-8000-000000000004","role":"authenticated"}';
set local role authenticated;
select is((select public.request_organization_access('c2000000-0000-4000-8000-000000000001','FIREFIGHTER')->>'result'),'NOT_ALLOWED','locked account cannot submit');
select is((select count(*)::integer from public.discover_organizations('10000000-0000-4000-8000-000000000001')),0,'locked account cannot discover organizations');
reset role;
set local request.jwt.claims='{"sub":"c1000000-0000-4000-8000-000000000005","role":"authenticated"}';
set local role authenticated;
select is((select public.request_organization_access('c2000000-0000-4000-8000-000000000001','FIREFIGHTER')->>'result'),'NOT_ALLOWED','locked account cannot submit');
select is((select count(*)::integer from public.discover_organizations('10000000-0000-4000-8000-000000000001')),0,'locked account cannot discover organizations');
reset role;
select throws_ok($test$insert into public.organization_access_requests(user_id,organization_id,requested_role) values ('c1000000-0000-4000-8000-000000000001','c2000000-0000-4000-8000-000000000001','MANAGER')$test$,'23505',null,'database partial unique index rejects duplicate pending');
select throws_ok($test$insert into public.organization_access_requests(user_id,organization_id,requested_role,status) values ('c1000000-0000-4000-8000-000000000006','c2000000-0000-4000-8000-000000000001','ADMIN','PENDING')$test$,'23514',null,'database role/status CHECK enforced');
select throws_ok($test$insert into public.organization_access_requests(user_id,organization_id,requested_role,status) values ('c1000000-0000-4000-8000-000000000006','c2000000-0000-4000-8000-000000000001','FIREFIGHTER','UNKNOWN')$test$,'23514',null,'database role/status CHECK enforced');
insert into public.organization_access_requests(user_id,organization_id,requested_role,status,reviewed_by,reviewed_at) values ('c1000000-0000-4000-8000-000000000006','c2000000-0000-4000-8000-000000000001','FIREFIGHTER','REJECTED','c1000000-0000-4000-8000-000000000003',now()),('c1000000-0000-4000-8000-000000000006','c2000000-0000-4000-8000-000000000001','MANAGER','APPROVED','c1000000-0000-4000-8000-000000000003',now());
reset role;
set local request.jwt.claims='{"sub":"c1000000-0000-4000-8000-000000000006","role":"authenticated"}';
set local role authenticated;
select is((select public.request_organization_access('c2000000-0000-4000-8000-000000000001','FIREFIGHTER')->>'result'),'SUBMITTED','historical closed requests do not block new pending');
select is((select count(*)::integer from public.list_my_access_requests()),3,'own history includes approved rejected and pending');
reset role;
set local request.jwt.claims='{}';
set local role authenticated;
select is((select public.request_organization_access('c2000000-0000-4000-8000-000000000001','FIREFIGHTER')->>'result'),'NOT_ALLOWED','missing JWT identity denies requests');
select is((select count(*)::integer from public.discover_organizations('10000000-0000-4000-8000-000000000001')),0,'missing identity denies discovery');
reset role;
select ok((select proconfig @> array['search_path=""'] from pg_proc where oid='public.discover_organizations(uuid,uuid,uuid)'::regprocedure),'discover_organizations(uuid,uuid,uuid) fixed search_path');
select ok(not has_function_privilege('anon','public.discover_organizations(uuid,uuid,uuid)','EXECUTE'),'discover_organizations(uuid,uuid,uuid) anonymous execution revoked');
select ok((select proconfig @> array['search_path=""'] from pg_proc where oid='public.request_organization_access(uuid,text)'::regprocedure),'request_organization_access(uuid,text) fixed search_path');
select ok(not has_function_privilege('anon','public.request_organization_access(uuid,text)','EXECUTE'),'request_organization_access(uuid,text) anonymous execution revoked');
select ok((select proconfig @> array['search_path=""'] from pg_proc where oid='public.list_my_access_requests(timestamptz,uuid)'::regprocedure),'list_my_access_requests(timestamptz,uuid) fixed search_path');
select ok(not has_function_privilege('anon','public.list_my_access_requests(timestamptz,uuid)','EXECUTE'),'list_my_access_requests(timestamptz,uuid) anonymous execution revoked');
select is((select count(*)::integer from public.user_organizations where user_id='c1000000-0000-4000-8000-000000000001'),0,'all attacks created no Google-user membership');
select is((select account_status from public.profiles where id='c1000000-0000-4000-8000-000000000001'),'PENDING_APPROVAL','all attacks left Google account pending');
select * from finish();
rollback;
